#include "window.h"
#include <QtWidgets>
#include <QSettings>
#include "soapyradio.h"
void Window::reloadDevices(){
 QSignalBlocker blocker(devices_);QString previous=devices_->currentData().toString();QString previousName=devices_->currentText();if(previous.isEmpty())previous=QSettings(settingsFile_,QSettings::IniFormat).value("rx/device").toString();devices_->clear();for(auto d:Receiver::deviceInfos())devices_->addItem(d.name,d.key);if(radio_.isRunning()&&!previous.isEmpty()&&devices_->findData(previous)<0)devices_->addItem(previousName,previous);int selected=devices_->findData(previous);if(selected>=0)devices_->setCurrentIndex(selected);
}
void Window::soapyOptions(){
 auto key=devices_->currentData().toString();if(radio_.isRunning()&&radio_.config.deviceKey==key){technical("Arrêtez ce SDR avant d'interroger ou modifier ses capacités Soapy");return;}
 auto c=SoapyRadio::capabilities(key);if(!c.error.isEmpty()){technical(c.error);QMessageBox::warning(this,"Capacités SDR",c.error);return;}QSettings prefs(settingsFile_,QSettings::IniFormat);QString prefix="soapy/"+key.mid(6)+"/";QDialog dialog(this);dialog.setWindowTitle("Capacités SoapySDR interrogées sur le matériel");auto form=new QFormLayout(&dialog);auto description=new QLabel(QString("%1 — RX %2 à %3 MHz\nGains : %4\nLes paramètres non annoncés par le pilote sont désactivés.").arg(c.backend).arg(c.frequencyMin/1e6).arg(c.frequencyMax/1e6).arg(c.gains.join(", ")));description->setWordWrap(true);form->addRow(description);
 auto rate=new QComboBox;for(double r:c.rates)if(r>=120000&&r<=20000000)rate->addItem(QString::number(r,'f',0),r);if(c.rates.isEmpty()){rate->setEditable(true);rate->addItem(QString::number(prefs.value(prefix+"rate",c.rateMin>0?c.rateMin:240000).toDouble(),'f',0));}else{int i=rate->findData(prefs.value(prefix+"rate",240000).toDouble());rate->setCurrentIndex(qMax(0,i));}form->addRow("IQ éch/s",rate);auto automatic=new QCheckBox("AGC pris en charge");automatic->setEnabled(c.agc);automatic->setChecked(c.agc&&prefs.value(prefix+"agc",false).toBool());form->addRow(automatic);
 auto bandwidth=new QSpinBox;bandwidth->setRange(0,20000000);bandwidth->setSpecialValueText("Automatique");bandwidth->setEnabled(c.bandwidth);bandwidth->setValue(c.bandwidth?prefs.value(prefix+"bandwidth",0).toInt():0);form->addRow("Bande matérielle Hz",bandwidth);auto antenna=new QComboBox;antenna->addItem("Automatique",QString{});for(auto name:c.antennas)antenna->addItem(name,name);antenna->setEnabled(!c.antennas.isEmpty());antenna->setCurrentIndex(qMax(0,antenna->findData(prefs.value(prefix+"antenna").toString())));form->addRow("Antenne",antenna);
 auto gain=new QDoubleSpinBox;gain->setRange(c.gainMin,c.gainMax);gain->setValue(gain_->value());gain->setEnabled(!c.gains.isEmpty());form->addRow("Gain dB",gain);auto ppm=new QSpinBox;ppm->setRange(-200,200);ppm->setValue(c.ppm?int(ppm_->value()):0);ppm->setEnabled(c.ppm);form->addRow("Correction PPM",ppm);auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);form->addRow(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{bool ok;double r=rate->currentText().toDouble(&ok);if(!ok||r<120000||r>20000000||(c.rateMin>0&&(r<c.rateMin||r>c.rateMax))){QMessageBox::warning(&dialog,"Taux IQ","Taux non valide ou hors des capacités annoncées (limite logicielle 120 kéch/s à 20 Méch/s)");return;}prefs.setValue(prefix+"rate",r);prefs.setValue(prefix+"agc",automatic->isChecked());prefs.setValue(prefix+"bandwidth",bandwidth->value());prefs.setValue(prefix+"antenna",antenna->currentData());prefs.sync();gain_->setEnabled(gain->isEnabled());gain_->setRange(c.gainMin,c.gainMax);gain_->setValue(gain->value());ppm_->setEnabled(c.ppm);ppm_->setValue(ppm->value());if(c.frequencyMax>c.frequencyMin)frequency_->setRange(qMax(.001,c.frequencyMin/1e6),qMin(4294.967295,c.frequencyMax/1e6));dialog.accept();});dialog.exec();
}
void Window::receiverOptions(){
 if(devices_->currentData().toString().startsWith("soapy:")){soapyOptions();return;}
 QSettings s(settingsFile_,QSettings::IniFormat);QDialog dialog(this);dialog.setWindowTitle("Récepteur SDR — réglages appliqués au matériel");auto form=new QFormLayout(&dialog);bool hack=devices_->currentData().toString().startsWith("hackrf:");auto automatic=new QCheckBox("Gain automatique RTL-SDR");automatic->setEnabled(!hack);automatic->setChecked(!hack&&s.value("rx/agc",false).toBool());form->addRow(automatic);auto rate=new QComboBox;for(int r:hack?QList<int>{2000000,4000000,8000000,10000000,20000000}:QList<int>{240000,256000,1024000,2048000,2400000})rate->addItem(QString::number(r)+" éch/s",r);int selected=rate->findData(s.value("rx/rate",hack?2000000:240000));rate->setCurrentIndex(qMax(0,selected));form->addRow("Taux IQ",rate);
 auto bandwidth=new QSpinBox;bandwidth->setRange(0,20000000);bandwidth->setSpecialValueText("Automatique pilote");bandwidth->setValue(s.value("rx/bandwidth",0).toInt());form->addRow("Filtre matériel Hz",bandwidth);auto channel=new QSpinBox;channel->setRange(8000,40000);channel->setValue(s.value("rx/channelBandwidth",21000).toInt());form->addRow("Filtre canal DSP Hz",channel);auto squelch=new QDoubleSpinBox;squelch->setRange(-160,0);squelch->setSpecialValueText("Désactivé");squelch->setValue(s.value("rx/squelch",-160).toDouble());form->addRow("Squelch puissance IQ dBFS",squelch);auto vga=new QSpinBox;vga->setRange(0,62);vga->setSingleStep(2);vga->setValue(s.value("rx/vga",20).toInt());vga->setEnabled(hack);form->addRow("Gain VGA HackRF dB",vga);auto reconnect=new QCheckBox("Reconnexion automatique au même SDR");reconnect->setChecked(s.value("rx/reconnect",true).toBool());form->addRow(reconnect);auto warning=new QLabel("RTL : gain manuel choisi au pas supporté le plus proche. HackRF : LNA par pas de 8 dB, VGA par pas de 2 dB ; correction PPM sur la fréquence demandée. Modifier ces paramètres redémarre la chaîne.");warning->setWordWrap(true);form->addRow(warning);
 auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);form->addRow(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{if(hack&&bandwidth->value()>rate->currentData().toInt()){QMessageBox::warning(&dialog,"Bande passante","La bande matérielle doit être inférieure au taux IQ.");return;}s.setValue("rx/agc",automatic->isChecked());s.setValue("rx/rate",rate->currentData());s.setValue("rx/bandwidth",bandwidth->value());s.setValue("rx/channelBandwidth",channel->value());s.setValue("rx/squelch",squelch->value());s.setValue("rx/vga",vga->value());s.setValue("rx/reconnect",reconnect->isChecked());s.sync();dialog.accept();if(radio_.isRunning())retune();});dialog.exec();
}
